commands.command:
cat > /tmp/galera_sst.te <<'EOF'
module galera_sst 1.0;

require {
	type mysqld_t;
	class unix_stream_socket connectto;
}

#============= mysqld_t ==============
allow mysqld_t self:unix_stream_socket connectto;
EOF
checkmodule -M -m -o /tmp/galera_sst.mod /tmp/galera_sst.te
semodule_package -o /tmp/galera_sst.pp -m /tmp/galera_sst.mod
semodule -i /tmp/galera_sst.pp
semodule -l | grep galera_sst
